BEGIN;
ALTER TABLE users ADD COLUMN IF NOT EXISTS tenant_id TEXT;
CREATE TABLE IF NOT EXISTS listening_surveys(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,name TEXT NOT NULL,purpose TEXT NOT NULL,consent_notice TEXT NOT NULL,minimum_cohort_size INTEGER NOT NULL CHECK(minimum_cohort_size>=5),retention_days INTEGER NOT NULL CHECK(retention_days BETWEEN 1 AND 730),questions JSONB NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('draft','open','closed','archived')),created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS listening_responses(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,survey_id BIGINT NOT NULL REFERENCES listening_surveys(id),respondent_hash CHAR(64) NOT NULL,cohort_key TEXT NOT NULL,encrypted_response TEXT NOT NULL,consent_version TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(survey_id,respondent_hash));
CREATE TABLE IF NOT EXISTS cohort_analyses(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,survey_id BIGINT NOT NULL REFERENCES listening_surveys(id),cohort_key TEXT NOT NULL,response_count INTEGER NOT NULL CHECK(response_count>=5),analysis JSONB NOT NULL,method_version TEXT NOT NULL,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS listening_actions(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,cohort_analysis_id BIGINT NOT NULL REFERENCES cohort_analyses(id),action TEXT NOT NULL,success_metric TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','reviewed','approved','rejected','in_progress','completed')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,reviewed_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS listening_connector_inbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,source TEXT NOT NULL,external_id TEXT NOT NULL,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,source,external_id));
CREATE TABLE IF NOT EXISTS listening_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,event_type TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS listening_cohort_idx ON listening_responses(tenant_id,survey_id,cohort_key,expires_at);
COMMIT;
